package configs

import (
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/xpzouying/xiaohongshu-mcp/cookies"
)

// TestResolveFingerprintSeed 校验 seed 取值优先级：环境变量 > 会话文件 > 新生成并写回。
func TestResolveFingerprintSeed(t *testing.T) {
	newStore := func(t *testing.T) cookies.Cookier {
		t.Helper()
		return cookies.NewLoadCookie(filepath.Join(t.TempDir(), "cookies.json"))
	}

	t.Run("环境变量优先于文件", func(t *testing.T) {
		t.Setenv("XHS_FP_SEED", "11111")
		store := newStore(t)
		assert.NoError(t, store.SaveSeed(22222))

		assert.Equal(t, 11111, ResolveFingerprintSeed(store))
	})

	t.Run("没有环境变量时用文件里的", func(t *testing.T) {
		t.Setenv("XHS_FP_SEED", "")
		store := newStore(t)
		assert.NoError(t, store.SaveSeed(22222))

		assert.Equal(t, 22222, ResolveFingerprintSeed(store))
	})

	t.Run("都没有时生成一个并写回，下次读到同一个", func(t *testing.T) {
		t.Setenv("XHS_FP_SEED", "")
		store := newStore(t)

		got := ResolveFingerprintSeed(store)
		assert.Positive(t, got)
		// 关键：必须落盘，否则下次启动又换一套
		assert.Equal(t, got, store.LoadSeed())
		assert.Equal(t, got, ResolveFingerprintSeed(store))
	})
}

package humanize

import (
	"math"
	"math/rand"
	"time"
)

type Action string

const (
	AfterClick    Action = "after_click"
	AfterType     Action = "after_type"
	AfterNavigate Action = "after_navigate"
	BetweenScroll Action = "between_scroll"
	BeforeSubmit  Action = "before_submit"
	BeforeClick   Action = "before_click"
	Reading       Action = "reading"
	Keystroke     Action = "keystroke"
	ClickHold     Action = "click_hold"
	AfterInteract Action = "after_interact"
	PointerSettle Action = "pointer_settle"
)

type LogNormal struct {
	Mu, Sigma float64
	Min, Max  time.Duration
}

func (l LogNormal) sample(norm float64) time.Duration {
	secs := math.Exp(l.Mu + l.Sigma*norm)
	// 转换前先处理上限：secs 极大时 float64→Duration 会溢出成负值
	if l.Max > 0 && secs >= l.Max.Seconds() {
		return l.Max
	}
	d := time.Duration(secs * float64(time.Second))
	if d < l.Min {
		return l.Min
	}
	return d
}

func (l LogNormal) Sample() time.Duration {
	return l.sample(rand.NormFloat64())
}

type TimingProfile map[Action]LogNormal

type Provider interface {
	Timing() TimingProfile
}

type DefaultProvider struct{}

func (DefaultProvider) Timing() TimingProfile {
	return TimingProfile{
		AfterClick:    {Mu: -0.92, Sigma: 0.35, Min: 150 * time.Millisecond, Max: 2 * time.Second},
		AfterType:     {Mu: -0.51, Sigma: 0.40, Min: 200 * time.Millisecond, Max: 3 * time.Second},
		AfterNavigate: {Mu: 0.41, Sigma: 0.45, Min: 600 * time.Millisecond, Max: 6 * time.Second},
		BetweenScroll: {Mu: -0.22, Sigma: 0.40, Min: 250 * time.Millisecond, Max: 3 * time.Second},
		BeforeSubmit:  {Mu: 0.0, Sigma: 0.40, Min: 400 * time.Millisecond, Max: 4 * time.Second},
		BeforeClick:   {Mu: -1.61, Sigma: 0.45, Min: 80 * time.Millisecond, Max: 1 * time.Second},
		Reading:       {Mu: -0.36, Sigma: 0.40, Min: 300 * time.Millisecond, Max: 3 * time.Second},
		Keystroke:     {Mu: -2.12, Sigma: 0.50, Min: 30 * time.Millisecond, Max: 400 * time.Millisecond},
		ClickHold:     {Mu: -2.47, Sigma: 0.33, Min: 45 * time.Millisecond, Max: 250 * time.Millisecond},
		AfterInteract: {Mu: 0.88, Sigma: 0.30, Min: 2 * time.Second, Max: 3 * time.Second},
		PointerSettle: {Mu: -1.20, Sigma: 0.35, Min: 200 * time.Millisecond, Max: 1200 * time.Millisecond},
	}
}

var defaultProvider Provider = DefaultProvider{}

func SetProvider(p Provider) {
	if p != nil {
		defaultProvider = p
	}
}

package xiaohongshu

import (
	"context"
	"log/slog"
	"os"
	"time"

	"github.com/go-rod/rod"
	"github.com/pkg/errors"
	"github.com/sirupsen/logrus"
	"github.com/xpzouying/xiaohongshu-mcp/humanize"
)

// PublishVideoContent 发布视频内容
type PublishVideoContent struct {
	Title        string
	Content      string
	Tags         []string
	VideoPath    string
	ScheduleTime *time.Time // 定时发布时间，nil 表示立即发布
	IsOriginal   bool       // 是否声明原创
	Visibility   string     // 可见范围: "公开可见"(默认), "仅自己可见", "仅互关好友可见"
	Products     []string   // 商品关键词列表，用于绑定带货商品
}

// NewPublishVideoAction 进入发布页并切换到"上传视频"
func NewPublishVideoAction(page *rod.Page) (*PublishAction, error) {
	pp := page.Timeout(300 * time.Second)

	if err := ensureCreatorSession(pp); err != nil {
		return nil, err
	}

	if err := pp.Navigate(urlOfPublic); err != nil {
		return nil, errors.Wrap(err, "导航到发布页面失败")
	}

	// 使用 WaitLoad 代替 WaitIdle（更宽松）
	if err := pp.WaitLoad(); err != nil {
		logrus.Warnf("等待页面加载出现问题: %v，继续尝试", err)
	}
	time.Sleep(2 * time.Second)

	if err := pp.WaitDOMStable(time.Second, 0.1); err != nil {
		logrus.Warnf("等待 DOM 稳定出现问题: %v，继续尝试", err)
	}
	time.Sleep(1 * time.Second)

	if err := mustClickPublishTab(pp, "上传视频"); err != nil {
		return nil, errors.Wrap(err, "切换到上传视频失败")
	}

	time.Sleep(1 * time.Second)

	return &PublishAction{page: pp}, nil
}

// PublishVideo 上传视频并提交
func (p *PublishAction) PublishVideo(ctx context.Context, content PublishVideoContent) error {
	if content.VideoPath == "" {
		return errors.New("视频不能为空")
	}

	// 重设超时：.Context(ctx) 会替换掉 NewPublishVideoAction 里 Timeout(300s) 的 deadline
	page := p.page.Context(ctx).Timeout(300 * time.Second)

	if err := uploadVideo(page, content.VideoPath); err != nil {
		return errors.Wrap(err, "小红书上传视频失败")
	}

	if err := submitPublishVideo(ctx, page, content.Title, content.Content, content.Tags, content.ScheduleTime, content.IsOriginal, content.Visibility, content.Products); err != nil {
		return errors.Wrap(err, "小红书发布失败")
	}
	return nil
}

// uploadVideo 上传单个本地视频
func uploadVideo(page *rod.Page, videoPath string) error {
	pp := page.Timeout(5 * time.Minute) // 视频处理耗时更长

	if _, err := os.Stat(videoPath); os.IsNotExist(err) {
		return errors.Wrapf(err, "视频文件不存在: %s", videoPath)
	}

	// 寻找文件上传输入框（与图文一致的 class，或退回到 input[type=file]）
	var fileInput *rod.Element
	var err error
	fileInput, err = pp.Element(".upload-input")
	if err != nil || fileInput == nil {
		fileInput, err = pp.Element("input[type='file']")
		if err != nil || fileInput == nil {
			return errors.New("未找到视频上传输入框")
		}
	}

	fileInput.MustSetFiles(videoPath)

	// 对于视频，等待发布按钮变为可点击即表示处理完成
	btn, err := waitForPublishButtonClickable(pp, 10*time.Minute)
	if err != nil {
		return err
	}
	slog.Info("视频上传/处理完成，发布按钮可点击", "btn", btn)
	return nil
}

// submitPublishVideo 填写标题、正文、标签并点击发布（等待按钮可点击后再提交）
func submitPublishVideo(ctx context.Context, page *rod.Page, title, content string, tags []string, scheduleTime *time.Time, isOriginal bool, visibility string, products []string) error {
	// 标题
	titleElem, err := page.Element("div.d-input input")
	if err != nil {
		return errors.Wrap(err, "查找标题输入框失败")
	}
	if err := humanize.Type(ctx, titleElem, title); err != nil {
		return errors.Wrap(err, "输入标题失败")
	}
	humanize.Delay(ctx, humanize.AfterType)

	// 正文 + 标签
	contentElem, err := getContentElement(page, contentElemTimeout)
	if err != nil {
		return err
	}
	if err := humanize.Type(ctx, contentElem, content); err != nil {
		return errors.Wrap(err, "输入正文失败")
	}
	tryRefocusTitle(page)
	if err := inputTags(ctx, contentElem, tags); err != nil {
		return err
	}

	humanize.Delay(ctx, humanize.AfterType)

	// 处理定时发布
	if scheduleTime != nil {
		if err := setSchedulePublish(ctx, page, *scheduleTime); err != nil {
			return errors.Wrap(err, "设置定时发布失败")
		}
		slog.Info("定时发布设置完成", "schedule_time", scheduleTime.Format("2006-01-02 15:04"))
	}

	// 设置可见范围
	if err := setVisibility(page, visibility); err != nil {
		return errors.Wrap(err, "设置可见范围失败")
	}

	// 处理原创声明：显式请求了原创但设置失败 → 报错中止，不静默发成非原创（避免"以为原创其实不是"）
	if isOriginal {
		if err := setOriginal(page); err != nil {
			return errors.Wrap(err, "设置原创声明失败（已请求原创，中止发布）")
		}
		slog.Info("已声明原创")
	}

	// 绑定商品
	if err := bindProducts(ctx, page, products); err != nil {
		return errors.Wrap(err, "绑定商品失败")
	}

	if err := clickPublishButton(page); err != nil {
		return err
	}

	// 校验发布真的成功（成功跳转离开发布页），未跳转判失败——消除假成功
	return waitPublishSuccess(page, 15*time.Second)
}

#!/usr/bin/env python3
"""比较同次构建的镜像，拒绝 GUI 新增或升级为高危的漏洞告警。"""

import collections
import json
import os
from pathlib import Path
import sys


LEVELS = {name: rank for rank, name in enumerate(
    ("Unknown", "Negligible", "Low", "Medium", "High", "Critical")
)}


def findings(path):
    result = {}
    for match in json.loads(Path(path).read_text())["matches"]:
        vulnerability, artifact = match["vulnerability"], match["artifact"]
        key = (vulnerability["id"], artifact["name"], artifact["type"])
        rank = LEVELS[vulnerability["severity"]]
        if key not in result or rank > result[key][0]:
            result[key] = (rank, vulnerability["severity"])
    return result


def main(base_path, gui_path):
    base, gui = findings(base_path), findings(gui_path)
    introduced = sorted(
        key for key, (rank, _) in gui.items()
        if rank >= LEVELS["High"] and rank > base.get(key, (-1, ""))[0]
    )
    lines = ["## 镜像漏洞扫描", "",
             "基线告警单独跟进；本检查拒绝 GUI 新增或严重度升高的 High/Critical 告警。", ""]
    for label, results in (("无 GUI 基线", base), ("GUI 镜像", gui)):
        counts = collections.Counter(severity for _, severity in results.values())
        lines.append(f"- {label}：{dict(counts)}")
    lines.append(f"- 新增或升级的 High/Critical：{len(introduced)}")
    for identifier, package, kind in introduced:
        lines.append(f"  - {identifier}: {package} ({kind})")
    report = "\n".join(lines) + "\n"
    print(report)
    if os.environ.get("GITHUB_STEP_SUMMARY"):
        with open(os.environ["GITHUB_STEP_SUMMARY"], "a") as summary:
            summary.write(report)
    return bool(introduced)


if __name__ == "__main__":
    if len(sys.argv) != 3:
        raise SystemExit("用法：check_vulnerabilities.py <base.json> <gui.json>")
    sys.exit(main(*sys.argv[1:]))

